+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+
+/** Immutable filter shared by page and count queries. */
+public record CustomerFilter(List<String> terms, Set<CustomerStatus> statuses) {
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        terms = List.copyOf(terms);
+        statuses = Set.copyOf(statuses);
+    }
+
+    public CustomerFilter(String name, Set<CustomerStatus> statuses) {
+        this(Arrays.stream(normalize(name).split("(?U)\\s+"))
+                .filter(term -> !term.isEmpty()).toList(), statuses);
+    }
+
+    public boolean matches(Customer customer) {
+        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
+            return false;
+        }
+        String first = normalize(customer.firstName());
+        String last = normalize(customer.lastName());
+        return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
+    }
+
+    private static String normalize(String value) {
+        return Normalizer.normalize(value, Normalizer.Form.NFD)
+                .replaceAll("\\p{M}+", "").toLowerCase(Locale.ROOT);
+    }
+}
